"""Unit tests for inventory_repo deterministic vendored / minified / generated
detection — the layer that classifies files BEFORE analyze_repo's LLM call, so
vendored/minified assets are excluded reproducibly instead of riding on a
temp-1.0 coin-flip."""
from __future__ import annotations

import inventory_repo as inv


def _write(tmp_path, name, content):
    p = tmp_path / name
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content)
    return p


# A realistic chunk of normal source: long enough to clear the 500-byte floor
# of the line-density branch, but with normal newline density.
_NORMAL_SRC = "\n".join(f"def handler_{i}(request):\n    return render({i})" for i in range(30))


# ---- is_minified ----

def test_is_minified_by_min_js_suffix():
    assert inv.is_minified("static/js/app.min.js", "var x=1;\n") is True


def test_is_minified_by_bundle_suffix():
    assert inv.is_minified("assets/main.bundle.js", "x\n") is True


def test_is_minified_by_sourcemap_reference():
    sample = "function a(){return 1}\n//# sourceMappingURL=app.js.map\n"
    assert inv.is_minified("assets/app.js", sample) is True


def test_is_minified_by_long_line_density():
    # ~1600 chars on effectively one line — minification-shaped.
    assert inv.is_minified("static/lib.js", "var a=1," * 200) is True


def test_is_minified_false_on_normal_source():
    assert inv.is_minified("src/views.py", _NORMAL_SRC) is False


def test_is_minified_false_on_short_file():
    # Below the 500-byte floor, no suffix, no sourcemap → not minified.
    assert inv.is_minified("src/tiny.js", "const x = 1\n") is False


# ---- is_generated_file folds in minification + markers ----

def test_is_generated_file_catches_minified(tmp_path):
    p = _write(tmp_path, "app.min.js", "var x=1;\n")
    assert inv.is_generated_file("static/app.min.js", p) is True


def test_is_generated_file_catches_at_generated_marker(tmp_path):
    p = _write(tmp_path, "schema.py", "# @generated by codegen tool\nX = 1\n")
    assert inv.is_generated_file("src/schema.py", p) is True


def test_is_generated_file_false_on_normal_source(tmp_path):
    p = _write(tmp_path, "views.py", _NORMAL_SRC)
    assert inv.is_generated_file("app/views.py", p) is False


# ---- categorize_file end-to-end ----

def test_categorize_excludes_minified_under_generated_exclude(tmp_path):
    p = _write(tmp_path, "app.min.js", "var x=1;" * 100)
    cat, tags, excluded, _reason = inv.categorize_file(
        "static/app.min.js", p, ".js", False,
        vendor_policy="exclude", generated_policy="exclude", test_policy="include",
        max_file_size=0,
    )
    assert excluded is True
    assert "generated" in tags


def test_categorize_excludes_bower_components_under_vendor_exclude(tmp_path):
    p = _write(tmp_path, "jquery.js", "function jq(){}\n")
    cat, tags, excluded, _reason = inv.categorize_file(
        "bower_components/jquery/jquery.js", p, ".js", False,
        vendor_policy="exclude", generated_policy="deprioritize", test_policy="include",
        max_file_size=0,
    )
    assert excluded is True
    assert "vendored" in tags


def test_categorize_keeps_normal_source(tmp_path):
    p = _write(tmp_path, "views.py", _NORMAL_SRC)
    cat, tags, excluded, _reason = inv.categorize_file(
        "app/views.py", p, ".py", False,
        vendor_policy="exclude", generated_policy="exclude", test_policy="include",
        max_file_size=0,
    )
    assert excluded is False
    assert "generated" not in tags and "vendored" not in tags


def test_categorize_excludes_capital_v_vendor_dir(tmp_path):
    # CakePHP / older-Composer convention uses capital-V "Vendor"; the vendored
    # path check is case-insensitive so these prune without manual globs.
    p = _write(tmp_path, "Guzzle.php", "<?php class Guzzle {}\n")
    cat, tags, excluded, _reason = inv.categorize_file(
        "app/Vendor/guzzle/Guzzle.php", p, ".php", False,
        vendor_policy="exclude", generated_policy="deprioritize", test_policy="include",
        max_file_size=0,
    )
    assert excluded is True
    assert "vendored" in tags


def test_categorize_excludes_nested_capital_v_vendor_in_plugin(tmp_path):
    # AvailablePlugin/<Plugin>/Vendor/... — nested capital-V vendored code.
    p = _write(tmp_path, "lib.php", "<?php\n")
    cat, tags, excluded, _reason = inv.categorize_file(
        "app/AvailablePlugin/CoManageDb/Vendor/dep/lib.php", p, ".php", False,
        vendor_policy="exclude", generated_policy="deprioritize", test_policy="include",
        max_file_size=0,
    )
    assert excluded is True
    assert "vendored" in tags


def test_categorize_capital_t_test_dir_is_support(tmp_path):
    # Capital-T "Test" (CakePHP) is treated as test/support, case-insensitively.
    p = _write(tmp_path, "FooTest.php", "<?php\n")
    cat, tags, excluded, _reason = inv.categorize_file(
        "app/Test/Case/FooTest.php", p, ".php", False,
        vendor_policy="exclude", generated_policy="deprioritize", test_policy="exclude",
        max_file_size=0,
    )
    assert excluded is True
    assert "support" in tags
